#!/bin/sh
set -eu
printf '%s\n' 'Terminal Games connection repair (not a reinstall).' 'Close Terminal Games, then press Enter to repair its connection.'
read -r answer
python_bin=''
for candidate in /Library/Frameworks/Python.framework/Versions/3.13/bin/python3 /opt/homebrew/bin/python3 /usr/local/bin/python3 python3; do
    if "$candidate" -c 'import sys; assert sys.version_info >= (3,9)' >/dev/null 2>&1; then python_bin="$candidate"; break; fi
done
if [ -z "$python_bin" ]; then printf '%s\n' 'Could not find the Python used by your game.'; read -r answer; exit 1; fi
status=0
"$python_bin" -c "import base64,zlib;exec(compile(zlib.decompress(base64.b64decode('')),'<Terminal Games connection repair>','exec'))" "$@" || status=$?
printf '%s\n' 'Press Enter to close.'
read -r answer
exit "$status"
